package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.nio.file.*;
import java.util.*;
import java.io.*;
import javax.imageio.ImageIO;
import static org.junit.Assert.*;

public class Alignment041Test {
    @org.junit.BeforeClass public static void softwareCameraControl()throws Exception{Path dir=Path.of("build/alignment041-controls");Files.createDirectories(dir);var image=image(.4,false);try(var out=Files.newOutputStream(dir.resolve("stationary.y4m"))){out.write("YUV4MPEG2 W400 H300 F5:1 Ip A1:1 C420jpeg\n".getBytes(java.nio.charset.StandardCharsets.US_ASCII));var yuv=new byte[400*300*3/2];for(int y=0;y<300;y++)for(int x=0;x<400;x++){int rgb=image.getRGB(x,y),r=(rgb>>16)&255,g=(rgb>>8)&255,b=rgb&255;yuv[y*400+x]=(byte)Math.max(0,Math.min(255,Math.round(16+.257*r+.504*g+.098*b)));}for(int y=0;y<300;y+=2)for(int x=0;x<400;x+=2){double u=0,v=0;for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++){int rgb=image.getRGB(x+dx,y+dy),r=(rgb>>16)&255,g=(rgb>>8)&255,b=rgb&255;u+=128-.148*r-.291*g+.439*b;v+=128+.439*r-.368*g-.071*b;}int at=(y/2)*200+x/2;yuv[120000+at]=(byte)Math.max(0,Math.min(255,Math.round(u/4)));yuv[150000+at]=(byte)Math.max(0,Math.min(255,Math.round(v/4)));}for(int frame=0;frame<30;frame++){out.write("FRAME\n".getBytes(java.nio.charset.StandardCharsets.US_ASCII));out.write(yuv);}}}
    static JSONObject geometry(){return new JSONObject().put("mode","homography").put("cameraKey","analytic041").put("note","LABELLED analytic software camera, .3m square; not user footage").put("imagePoints",new JSONArray("[[0.1,0.9],[0.9,0.9],[0.9,0.1],[0.1,0.1]]")).put("worldPoints",new JSONArray("[[0,0],[0.3,0],[0.3,0.3],[0,0.3]]")).put("anchorSigmaM",.003).put("scaleRelativeSigma",.01);}
    static JSONObject basis(){return new JSONObject().put("origin",new JSONArray("[0,0,0]")).put("u",new JSONArray("[1,0,0]")).put("v",new JSONArray("[0,0,-1]")).put("source","Declared analytic native placement");}
    static JSONObject tape(){return new JSONObject().put("a",new JSONArray("[0.3,0.5]")).put("b",new JSONArray("[0.6,0.5]")).put("markA",0).put("markB",.1125).put("unit","m").put("source","Independent analytic112.5mm length, not physical tape");}
    static JSONArray landmarks(){var out=new JSONArray();double[][] fit={{.1,.9,0,0},{.9,.9,.3,0},{.9,.1,.3,.3},{.1,.1,0,.3}},checks={{.3,.7,.075,.075},{.7,.3,.225,.225},{.3,.3,.075,.225}};int n=0;for(var rows:new double[][][]{fit,checks})for(var p:rows)out.put(new JSONObject().put("name","landmark"+n++).put("role",rows==fit?"fit":"check").put("image",new JSONArray(new double[]{p[0],p[1]})).put("native",new JSONArray(new double[]{p[2],0,-p[3]})).put("source","Independent declared analytic coordinate"));return out;}
    static BufferedImage image(double cx,boolean hidden){var image=new BufferedImage(400,300,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setColor(new Color(143,162,123));g.fillRect(0,0,400,300);g.setColor(new Color(64,85,63));for(int x=10;x<400;x+=20)g.drawLine(x,0,x,300);for(int y=10;y<300;y+=20)g.drawLine(0,y,400,y);g.setColor(new Color(20,20,20));g.fillRect(290,190,55,85);g.setColor(new Color(217,188,31));g.fillRect(292,191,51,17);if(!hidden){int x=(int)(cx*400)-14;g.setColor(new Color(19,22,24));g.fillRect(x,96,28,70);g.setColor(new Color(173,183,193));g.fillRect(x+2,96,24,14);g.setColor(new Color(186,35,28));g.fillRect(x+24,102,4,10);g.setColor(new Color(222,207,150));g.drawLine(x+8,112,x+19,112);}else{g.setColor(Color.WHITE);g.fillRect((int)(cx*400)-23,87,46,93);}g.dispose();return image;}
    static JSONObject frame(double cx,boolean hidden,double seconds)throws Exception{var out=new ByteArrayOutputStream();ImageIO.write(image(cx,hidden),"png",out);var b=out.toByteArray();return new JSONObject().put("image",Base64.getEncoder().encodeToString(b)).put("imageSha256",PerceptionStore.hash(b)).put("seconds",seconds);}
    static JSONArray target(double cx){return new JSONArray(new double[]{cx-.035,.32,cx+.035,.5533333333333333});}
    static JSONArray negatives(){return new JSONArray().put(new JSONArray("[0.725,0.6333333333333333,0.8625,0.9166666666666666]"));}
    static final class Fixture implements AutoCloseable {
        final Path root=Files.createTempDirectory("alignment041-test-");final WorldLedger ledger=new WorldLedger(root);final JSONObject world=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Analytic041");final JSONObject observed=ledger.observe(world.getString("id"));final String body=observed.getJSONObject("frame").getJSONArray("bodies").getJSONObject(0).getString("id");final Alignment041Store store=new Alignment041Store(root,ledger);final JSONObject reg;
        Fixture()throws Exception{var input=new JSONObject().put("worldId",world.getString("id")).put("expectedRevision",observed.getInt("expectedRevision")).put("expectedHash",observed.getString("expectedHash")).put("bodyId",body).put("geometry",geometry()).put("nativePlane",basis()).put("landmarks",landmarks()).put("tape",tape()).put("frame",frame(.4,false,0)).put("source","LABELLED analytic fixture, no private user camera");reg=store.register(input);assertTrue(reg.toString(),reg.getJSONObject("fit").getBoolean("passed"));}
        JSONObject start(String kind)throws Exception{return store.start(new JSONObject().put("registrationId",reg.getString("id")).put("cameraKey","analytic041").put("kind",kind).put("fromMark",0).put("toMark",.05).put("box",target(.4)).put("negativeBoxes",negatives()).put("frame",frame(.4,false,1)).put("label","Analytic software lighter").put("sourceClock","Declared analytic fixture seconds, not physical camera"));}
        JSONObject upload(JSONObject t,int n,double cx,boolean hidden,String phase)throws Exception{return store.frame(new JSONObject().put("id",t.getString("id")).put("generation",t.getInt("generation")).put("ordinal",n).put("cameraKey","analytic041").put("phase",phase).put("frame",frame(cx,hidden,1+n*.25)));}
        public void close(){}
    }
    @Test public void independentPlaneMappingAndWithheldGatesAreActualNumbers(){var fit=MatRegistration041.fit(geometry(),basis(),landmarks(),tape());assertTrue(fit.toString(),fit.getBoolean("passed"));assertEquals(1,fit.getDouble("scale"),1e-12);assertArrayEquals(new double[]{.12,0,-.21},MatRegistration041.map(fit,new double[]{.12,.21}),1e-12);assertEquals(0,fit.getDouble("maxCheckErrorM"),1e-12);var changed=landmarks();changed.getJSONObject(4).getJSONArray("native").put(0,.085);assertFalse(MatRegistration041.fit(geometry(),basis(),changed,tape()).getBoolean("passed"));var bad=basis().put("u",new JSONArray("[2,0,0]"));assertThrows(IllegalArgumentException.class,()->MatRegistration041.fit(geometry(),bad,landmarks(),tape()));}
    @Test public void similarityRotationTranslationAndScaleAreNotForcedToIdentity(){var b=basis().put("origin",new JSONArray("[1,0.5,2]")).put("u",new JSONArray("[0,0,1]")).put("v",new JSONArray("[1,0,0]"));var marks=landmarks();double a=Math.cos(.4),q=Math.sin(.4);for(Object raw:marks){var l=(JSONObject)raw;var v=l.getJSONArray("native");double x=v.getDouble(0),y=-v.getDouble(2),nx=.04+a*x-q*y,ny=-.02+q*x+a*y;l.put("native",new JSONArray(new double[]{1+ny,.5,2+nx}));}var fit=MatRegistration041.fit(geometry(),b,marks,tape());assertTrue(fit.toString(),fit.getBoolean("passed"));assertEquals(Math.toDegrees(.4),fit.getDouble("rotationDeg"),1e-10);assertArrayEquals(new double[]{1-.02+q*.1+a*.2,.5,2+.04+a*.1-q*.2},MatRegistration041.map(fit,new double[]{.1,.2}),1e-12);for(Object raw:marks){var p=((JSONObject)raw).getJSONArray("native");p.put(0,1+(p.getDouble(0)-1)*1.07).put(2,2+(p.getDouble(2)-2)*1.07);}assertFalse(MatRegistration041.fit(geometry(),b,marks,tape()).getBoolean("passed"));}
    @Test public void targetUsesFixedColourBackgroundAndRecoversAfterOcclusion(){var tracker=new MatTarget041(image(.4,false),target(.4),negatives(),new PlaneCalibration(geometry()));for(int n=0;n<4;n++){var r=tracker.update(image(.4+n*.005,false));assertTrue(r.toString(),r.getBoolean("accepted"));assertEquals(.4+n*.005,r.getJSONArray("point").getDouble(0),.005);}for(int n=0;n<3;n++)assertFalse(tracker.update(image(.415,true)).getBoolean("accepted"));var recovered=tracker.update(image(.415,false));assertTrue(recovered.toString(),recovered.getBoolean("accepted"));assertEquals("reacquired",recovered.getString("status"));}
    @Test public void fixedManualWindowsRejectLateFramesAndFirstEvaluationSurvivesRestart()throws Exception{try(var f=new Fixture()){var t=f.start("stationary");for(int n=1;n<=12;n++)f.upload(t,n,.4,false,"start");assertThrows(IllegalStateException.class,()->f.upload(t,13,.4,false,"start"));f.store.finish(t.getString("id"),false);var run=f.store.trial(t.getString("id"));var refs=new JSONArray();for(Object raw:run.getJSONArray("trace")){var row=(JSONObject)raw;refs.put(new JSONObject().put("ordinal",row.getInt("ordinal")).put("imageSha256",row.getJSONObject("frame").getString("imageSha256")).put("visible",true));}var args=new JSONObject().put("id",t.getString("id")).put("references",new JSONObject().put("source","Independent labelled software originals, stationary by construction").put("confirmed",true).put("frames",refs));var result=f.store.evaluate(args);assertTrue(result.toString(),result.getBoolean("passed"));assertThrows(IllegalStateException.class,()->f.store.evaluate(args));var reopened=new Alignment041Store(f.root,f.ledger);assertTrue(result.similar(reopened.trial(t.getString("id")).getJSONObject("evaluation")));assertTrue(f.observed.similar(f.ledger.observe(f.world.getString("id"))));}}
    @Test public void phaseAndGenerationFencesKeepOriginalPrefixAndSourceTamperingIsRefused()throws Exception{try(var f=new Fixture()){var t=f.start("occlusion");for(int n=1;n<=8;n++)f.upload(t,n,.4,false,"start");f.store.mark(new JSONObject().put("id",t.getString("id")).put("generation",1).put("expectedOrdinal",8).put("phase","hidden"));assertThrows(IllegalStateException.class,()->f.upload(t,9,.4,true,"start"));f.upload(t,9,.4,true,"hidden");f.store.finish(t.getString("id"),true);assertThrows(IllegalStateException.class,()->f.upload(t,10,.4,true,"hidden"));var exported=f.store.image(t.getString("id"),9);assertEquals(frame(.4,true,3.25).getString("imageSha256"),exported.getJSONObject("reference").getString("imageSha256"));Files.write(f.root.resolve("alignment-041/frames/"+t.getString("id")+"/9.image"),new byte[]{1,2,3});assertThrows(IllegalStateException.class,()->f.store.image(t.getString("id"),9));}}
    @Test public void restartDoesNotResumeCameraAndStaleWorldCannotEnterNewTrial()throws Exception{try(var f=new Fixture()){var t=f.start("movement");f.upload(t,1,.4,false,"start");var reopened=new Alignment041Store(f.root,f.ledger);assertEquals("interrupted",reopened.trial(t.getString("id")).getString("status"));assertFalse(reopened.busy());f.ledger.restore(f.world.getString("id"),f.observed.getInt("expectedRevision"),f.observed.getString("expectedHash"),0,"");assertThrows(IllegalStateException.class,()->f.start("movement"));}}
    static JSONObject references(JSONObject run){var refs=new JSONArray();for(Object raw:run.getJSONArray("trace")){var row=(JSONObject)raw;if(!row.getString("phase").equals("transition"))refs.put(new JSONObject().put("ordinal",row.getInt("ordinal")).put("imageSha256",row.getJSONObject("frame").getString("imageSha256")).put("visible",!row.getString("phase").equals("hidden")).put("atDeclaredMark",true));}return new JSONObject().put("source","Independently known labelled image construction and declared physical-unit control; not real camera").put("confirmed",true).put("frames",refs);}
    static void mark(Fixture f,JSONObject t,int n,String phase)throws Exception{f.store.mark(new JSONObject().put("id",t.getString("id")).put("generation",t.getInt("generation")).put("expectedOrdinal",n).put("phase",phase));}
    @Test public void independentMetricMovementComesFromActualDifferentPixelsAndFixedEndpointWindows()throws Exception{try(var f=new Fixture()){var t=f.start("movement");for(int n=1;n<=8;n++)f.upload(t,n,.4,false,"start");mark(f,t,8,"transition");for(int n=9;n<=12;n++)f.upload(t,n,.4+(n-8)*.1333333333333333/4,false,"transition");mark(f,t,12,"end");for(int n=13;n<=20;n++)f.upload(t,n,.5333333333333333,false,"end");f.store.finish(t.getString("id"),false);var run=f.store.trial(t.getString("id"));var result=f.store.evaluate(new JSONObject().put("id",t.getString("id")).put("references",references(run)));assertTrue(result.toString(),result.getBoolean("passed"));assertEquals(.05,result.getJSONObject("metrics").getJSONArray("expectedDeltaM").getDouble(0),1e-12);assertEquals(.05,result.getJSONObject("metrics").getJSONArray("actualDeltaM").getDouble(0),.004);assertTrue(f.observed.similar(f.ledger.observe(f.world.getString("id"))));}}
    @Test public void manualOcclusionRejectsMeasurementsWhileHiddenAndRetainsMeasuredRecovery()throws Exception{try(var f=new Fixture()){var t=f.start("occlusion");for(int n=1;n<=8;n++)f.upload(t,n,.4,false,"start");mark(f,t,8,"hidden");for(int n=9;n<=16;n++)f.upload(t,n,.4,true,"hidden");mark(f,t,16,"revealed");for(int n=17;n<=24;n++)f.upload(t,n,.4,false,"revealed");f.store.finish(t.getString("id"),false);var run=f.store.trial(t.getString("id"));var refs=references(run);var wrong=WorldFrames.copy(refs);wrong.getJSONArray("frames").getJSONObject(8).put("visible",true);var unscored=MatTrials041.evaluate(run,wrong);assertEquals("unscored",unscored.getString("status"));assertFalse(unscored.getBoolean("passed"));var result=f.store.evaluate(new JSONObject().put("id",t.getString("id")).put("references",refs));assertTrue(result.toString(),result.getBoolean("passed"));assertEquals(0,result.getJSONObject("metrics").getInt("hiddenAcceptedMeasurements"));assertEquals(1,result.getJSONObject("metrics").getDouble("recoveryCoverage"),0);}}
    @Test public void realSourceProjectionPinsFullEvidenceAndRejectsChangedExports()throws Exception{try(var f=new Fixture();var nativeWorld=new WorldNativeStore(f.root);var oldObservations=new WorldObservationStore(f.root,f.ledger);var game=new EmbeddedGameClient(Path.of(".."),f.root)){var metrics=new MetricObservationStore(f.root,oldObservations,f.ledger);var tabletop=new TabletopStore(f.root, f.ledger,metrics);var knowledge=new KnowledgeStore(f.root,tabletop,true);var runtime=new SpatialRuntime040(f.root,f.ledger,nativeWorld,tabletop,knowledge,game);runtime.bind(new JSONObject().put("kind","world").put("worldId",f.world.getString("id")));var trial=f.start("stationary");f.upload(trial,1,.4,false,"start");var summary=f.store.capture(runtime.read(),true);var snapshot=f.store.cached(summary.getString("snapshotHash"));var view=Alignment041Report.view(snapshot,"top");assertEquals(summary.getString("snapshotHash"),view.getString("sourceSnapshotHash"));assertTrue(view.getJSONObject("registeredPoint").getBoolean("usable"));assertFalse(view.getJSONObject("registeredPoint").getBoolean("heightKnown"));var expected=MatRegistration041.map(f.reg.getJSONObject("fit"),PlaneCalibration.point(summary.getJSONObject("latest").getJSONObject("estimate").getJSONArray("positionM")));assertArrayEquals(expected,MatRegistration041.v3(view.getJSONObject("registeredPoint").getJSONArray("nativePlanePointM")),1e-12);var report=Alignment041Report.build(snapshot);assertFalse(report.getJSONObject("files").getString("index.html").contains("data:image"));var export=Alignment041Report.exported(snapshot);assertTrue(Alignment041Report.verify(export).getBoolean("passed"));export.getJSONObject("snapshot").getJSONObject("registration").getJSONObject("fit").put("scale",7);assertThrows(IllegalStateException.class,()->Alignment041Report.verify(export));assertTrue(f.observed.similar(f.ledger.observe(f.world.getString("id"))));}}
}
